import requests,wmill

def main():
 key=wmill.get_variable('u/Alp/OPENROUTER_API_KEY')
 r=requests.get('https://openrouter.ai/api/v1/guardrails',headers={'Authorization':'Bearer '+key},timeout=20)
 if r.status_code!=200:return {'http_status':r.status_code,'error':r.json().get('error')}
 return {'http_status':r.status_code,'guardrails':[{k:g.get(k) for k in ['id','name','limit_usd','reset_interval']} for g in r.json().get('data',[])]}
